/**
 * 지도 WebView 용 Pretendard 부분집합. **생성물이다 — 손으로 고치지 말 것.**
 *
 * 만드는 법과 이 파일이 존재하는 이유는 `scripts/build-map-font.py` 머리말에 있다.
 * 요약하면: WebView 는 앱이 올린 폰트를 볼 수 없어서, 지도 위 글자만 시스템 폰트로
 * 렌더되고 있었다. 통째로 넣기엔 무거워서 KS X 1001 2,350자 + ASCII 로 줄였다.
 */

/** Pretendard SemiBold 부분집합(WOFF2, 163,880 bytes). */
export const PRETENDARD_SEMIBOLD_WOFF2_BASE64 = ""

/** Pretendard Bold 부분집합(WOFF2, 165,572 bytes). */
export const PRETENDARD_BOLD_WOFF2_BASE64 = ""

/** `@font-face` 규칙. `mapHtml.ts` 가 스타일 맨 앞에 넣는다. */
export const MAP_FONT_FACE_CSS = [
  `@font-face {
    font-family: 'Pretendard';
    font-weight: 600;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${PRETENDARD_SEMIBOLD_WOFF2_BASE64}) format('woff2');
  }`,
  `@font-face {
    font-family: 'Pretendard';
    font-weight: 700;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${PRETENDARD_BOLD_WOFF2_BASE64}) format('woff2');
  }`,
].join("\n")
